import { ref, computed, onMounted, onBeforeUnmount } from 'vue'

/**
 * 画面サイズ判定（共通）
 * - mobile は <= 900px をデフォルトにする
 */
export function useViewport(options = {}) {
  const {
    mobileMax = 900,
    tabletMax = 1500
  } = options

  const width = ref(typeof window !== 'undefined' ? window.innerWidth : 1024)
  const height = ref(typeof window !== 'undefined' ? window.innerHeight : 768)

  function update() {
    width.value = window.innerWidth
    height.value = window.innerHeight
  }

  const isMobile = computed(() => width.value <= mobileMax)
  const isTablet = computed(() => width.value > mobileMax && width.value <= tabletMax)
  const isDesktop = computed(() => width.value > tabletMax)

  onMounted(() => {
    update()
    window.addEventListener('resize', update, { passive: true })
  })

  onBeforeUnmount(() => {
    window.removeEventListener('resize', update)
  })

  return { width, height, isMobile, isTablet, isDesktop }
}


