export const SCHEDULE_GRID_CLIPBOARD_SOURCE = 'supabasu-schedule-grid'
export const SCHEDULE_GRID_CLIPBOARD_VERSION = 2

export function serializeScheduleGridClipboard(cells) {
  return JSON.stringify({
    version: SCHEDULE_GRID_CLIPBOARD_VERSION,
    source: SCHEDULE_GRID_CLIPBOARD_SOURCE,
    cells,
  })
}

export function parseScheduleGridClipboard(text) {
  if (!text || typeof text !== 'string') return null
  try {
    const data = JSON.parse(text.trim())
    if (data?.source !== SCHEDULE_GRID_CLIPBOARD_SOURCE) return null
    if (!Array.isArray(data.cells)) return null
    return data.cells
  } catch {
    return null
  }
}

export function isSingleScheduleGridClipboardCell(cells) {
  return (
    Array.isArray(cells) &&
    cells.length === 1 &&
    Array.isArray(cells[0]) &&
    cells[0].length === 1
  )
}

export function scheduleGridClipboardCell(row) {
  if (!row) return null
  return {
    status1_id: row.schedule_status_id ?? null,
    status2_id: row.schedule_secondary_status_id ?? null,
    label: String(row.label ?? ''),
    start_on: row.start_on || null,
    end_on: row.end_on || null,
    note: String(row.note ?? ''),
  }
}

export function applyScheduleGridClipboardCell(targetRow, clipCell) {
  if (!targetRow || !clipCell) return
  targetRow.schedule_status_id = clipCell.status1_id ?? null
  targetRow.schedule_secondary_status_id = clipCell.status2_id ?? null
  targetRow.label = String(clipCell.label ?? '')
  if ('start_on' in clipCell) targetRow.start_on = clipCell.start_on || null
  if ('end_on' in clipCell) targetRow.end_on = clipCell.end_on || null
  if ('note' in clipCell) targetRow.note = String(clipCell.note ?? '')
}
