/**
 * モバイル等で「カメラで撮る」と OS / ブラウザが付けがちなファイル名だけを対象にする。
 * ギャラリーから選んだ通常のファイル名は変更しない（同名の実ファイルは稀なためヒューリスティックと割り切る）。
 * @type {ReadonlySet<string>}
 */
const LIKELY_BROWSER_CAMERA_CAPTURE_NAMES = new Set([
  'image.jpeg',
  'image.jpg',
  'image.jpe',
  'image.png',
  'image.heic',
  'image.heif',
  'photo.jpg',
  'photo.jpeg',
  'photo.png',
  'capture.jpg',
  'capture.jpeg'
])

/**
 * @param {string} originalName
 * @param {{ outputExt?: string }} [opts] アップロード直前に JPEG に統一する場合は 'jpg'
 * @returns {string}
 */
export function resolveCameraPlaceholderUploadName(originalName, opts = {}) {
  const raw = (originalName ?? '').trim()
  const lower = raw.toLowerCase()
  const outputExt = (opts.outputExt || 'jpg').replace(/^\./, '')

  if (outputExt.toLowerCase() === 'jpg' && /\.(heic|heif)$/i.test(raw)) {
    return raw.replace(/\.(heic|heif)$/i, '.jpg')
  }

  if (!LIKELY_BROWSER_CAMERA_CAPTURE_NAMES.has(lower)) {
    return raw || `upload.${outputExt}`
  }

  const d = new Date()
  const pad = (n) => String(n).padStart(2, '0')
  const ymd = `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}`
  const hms = `${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`
  const suffix = Math.random().toString(36).slice(2, 6)
  return `img_${ymd}_${hms}_${suffix}.${outputExt}`
}
