<template>
  <div v-if="isOpen" class="modal-overlay" @mousedown.stop @mouseup.stop>
    <div class="modal-content" @click.stop @mousedown.stop @mouseup.stop>
      <div class="modal-header">
        <h3>見積固定文字入力</h3>
        <button class="close-btn" @click="handleClose">✕</button>
      </div>

      <div class="modal-body">
        <div class="section-heading-row">
          <button
            type="button"
            class="section-toggle"
            :aria-expanded="isPdfFixedSectionOpen"
            :aria-label="isPdfFixedSectionOpen ? 'PDF固定文字を折りたたむ' : 'PDF固定文字を展開する'"
            @click.stop="isPdfFixedSectionOpen = !isPdfFixedSectionOpen"
          >
            {{ isPdfFixedSectionOpen ? '−' : '＋' }}
          </button>
          <h4 class="section-heading">PDF固定文字</h4>
        </div>
        <div v-show="isPdfFixedSectionOpen" class="pdf-fixed-section">
          <div
            v-for="(entry, index) in localPdfFixed"
            :key="`pdf-fixed-${entry.sort_order}`"
            class="label-row label-row--full"
          >
            <textarea
              class="label-textarea label-textarea--pdf-fixed"
              v-model="entry.label"
              :placeholder="`固定文字 ${index + 1}`"
              rows="3"
              @click.stop
              @mousedown.stop
              @mouseup.stop
            />
          </div>
        </div>

        <div class="section-divider" role="separator"></div>
        <h4 class="section-heading">部屋名</h4>

        <div
          v-for="index in defaultRoomOrders"
          :key="`room-${index}`"
          class="label-row"
        >
          <span class="label-number">{{ index }}.</span>
          <input
            type="text"
            class="label-input"
            v-model="localLabels[index]"
            :placeholder="`ラベル ${index}`"
            @click.stop
            @mousedown.stop
            @mouseup.stop
            @keydown.enter="blurInputOnEnterWhenNotComposing"
          />
        </div>

        <div class="section-divider" role="separator"></div>
        <h4 class="section-heading">入力補助</h4>

        <div
          v-for="index in assistRoomOrders"
          :key="`assist-${index}`"
          class="label-row"
        >
          <span class="label-number">{{ index }}.</span>
          <input
            type="text"
            class="label-input label-input--extended"
            v-model="localLabels[index]"
            :placeholder="`ラベル ${index}`"
            @click.stop
            @mousedown.stop
            @mouseup.stop
            @keydown.enter="blurInputOnEnterWhenNotComposing"
          />
        </div>
      </div>

      <div class="modal-footer">
        <button class="cancel-btn" @click="handleClose">キャンセル</button>
        <button class="save-btn" @click="handleSave">保存</button>
      </div>
    </div>
  </div>
</template>

<script setup>
import { computed, ref, watch } from 'vue'
import {
  ROOM_LABEL_COUNT,
  ROOM_LABEL_INSERT_MENU_ORDER_MIN,
  PHOTO_TAB_ROOM_ORDER_MAX,
  padRoomLabelSlots,
  padRoomLabelPdfFixedSlots,
} from '../constants/roomLabelSlots.js'
import { blurInputOnEnterWhenNotComposing } from '../utils/inputKeyboard.js'

const props = defineProps({
  isOpen: {
    type: Boolean,
    default: false,
  },
  labels: {
    type: Array,
    default: () => [],
  },
  pdfFixedLabels: {
    type: Array,
    default: () => [],
  },
})

const emit = defineEmits(['close', 'save'])

const localLabels = ref(Array(ROOM_LABEL_COUNT).fill(''))
const localPdfFixed = ref(padRoomLabelPdfFixedSlots([]))
const isPdfFixedSectionOpen = ref(false)

const defaultRoomOrders = computed(() =>
  Array.from({ length: PHOTO_TAB_ROOM_ORDER_MAX + 1 }, (_, i) => i)
)

const assistRoomOrders = computed(() =>
  Array.from(
    { length: ROOM_LABEL_COUNT - ROOM_LABEL_INSERT_MENU_ORDER_MIN },
    (_, i) => i + ROOM_LABEL_INSERT_MENU_ORDER_MIN
  )
)

function syncLocalFromProps() {
  const padded = padRoomLabelSlots(props.labels)
  localLabels.value = padded.map((l) => l.label || '')
  localPdfFixed.value = padRoomLabelPdfFixedSlots(props.pdfFixedLabels).map((row) => ({
    sort_order: row.sort_order,
    label: row.label || '',
  }))
}

watch(() => [props.labels, props.pdfFixedLabels], syncLocalFromProps, { immediate: true, deep: true })

watch(() => props.isOpen, (open) => {
  if (open) {
    isPdfFixedSectionOpen.value = localPdfFixed.value.some(
      (entry) => String(entry.label ?? '').trim().length > 0
    )
  }
})

function handleClose() {
  emit('close')
}

function handleSave() {
  const standard = localLabels.value.map((label, index) => ({
    sort_order: index,
    label: label || '',
  }))
  const pdfFixed = localPdfFixed.value.map((entry) => ({
    sort_order: entry.sort_order,
    label: entry.label || '',
  }))
  emit('save', [...standard, ...pdfFixed])
}
</script>

