/** 案件・テンプレのルームラベル枠数（sort_order 0 ～ ROOM_LABEL_COUNT - 1） */
export const ROOM_LABEL_COUNT = 20

/** 見積 PDF 固定文字（room_labels / room_label_templates 共通 sort_order） */
export const ROOM_LABEL_FIXED_TEXT_ORDERS = [101, 102, 103]

export const ROOM_LABEL_FIXED_TEXT_KEYS = ['fixed1', 'fixed2', 'fixed3']

/** 見積 PDF 固定文字の表示ラベル（モーダル用） */
export const ROOM_LABEL_FIXED_TEXT_LABELS = ['PDF固定1', 'PDF固定2', 'PDF固定3']

/** 写真タブのルーム別サムネ・photo_work_links 保存対象の最大 sort_order */
export const PHOTO_TAB_ROOM_ORDER_MAX = 9

export function isPhotoTabRoomOrder(ord) {
  const n = Number(ord)
  return Number.isFinite(n) && n >= 0 && n <= PHOTO_TAB_ROOM_ORDER_MAX
}

/** 部屋挿入メニュー用 sort_order（0〜9 は部屋枠のため除外、10〜19 を表示） */
export const ROOM_LABEL_INSERT_MENU_ORDER_MIN = 10

export function isStandardRoomLabelSortOrder(ord) {
  const n = Number(ord)
  return Number.isFinite(n) && n >= 0 && n < ROOM_LABEL_COUNT
}

export function isRoomLabelInsertMenuOrder(ord) {
  const n = Number(ord)
  return Number.isFinite(n) && n >= ROOM_LABEL_INSERT_MENU_ORDER_MIN && n < ROOM_LABEL_COUNT
}

export function isRoomLabelFixedTextOrder(ord) {
  const n = Number(ord)
  return ROOM_LABEL_FIXED_TEXT_ORDERS.includes(n)
}

export function isAllowedRoomLabelTemplateSortOrder(ord) {
  const n = Number(ord)
  if (!Number.isFinite(n)) return false
  if (isStandardRoomLabelSortOrder(n)) return true
  return isRoomLabelFixedTextOrder(n)
}

/** save_room_labels / Edge 側と揃えた許可 sort_order */
export function isAllowedWorkRoomLabelSortOrder(ord) {
  const n = Number(ord)
  if (!Number.isInteger(n)) return false
  if (n >= 0 && n <= 99) return true
  return isRoomLabelFixedTextOrder(n)
}

function roomLabelMenuTexts(labels, orderFilter) {
  return [...(labels || [])]
    .filter((r) => orderFilter(Number(r?.sort_order)))
    .sort((a, b) => (Number(a?.sort_order) || 0) - (Number(b?.sort_order) || 0))
    .map((r) => String(r?.label ?? '').trim())
    .filter((t) => t.length > 0)
}

/** 部屋挿入ドロップダウン用ラベル文字列（sort_order 10〜19・空白除外） */
export function roomLabelInsertMenuTexts(labels) {
  return roomLabelMenuTexts(labels, isRoomLabelInsertMenuOrder)
}

/** pw-room-btn 用: sort_order 0〜19・空白除外（101〜103 は含めない） */
export function roomLabelPwMenuTexts(labels) {
  return roomLabelMenuTexts(labels, isStandardRoomLabelSortOrder)
}

/** sort_order 0-19 のみ抽出 */
export function splitRoomLabelRows(rows) {
  const standard = []
  const pdfFixed = []
  for (const r of rows || []) {
    const o = Number(r?.sort_order)
    if (!Number.isFinite(o)) continue
    if (isRoomLabelFixedTextOrder(o)) pdfFixed.push(r)
    else if (isStandardRoomLabelSortOrder(o)) standard.push(r)
  }
  return { standard, pdfFixed }
}

/** sort_order ごとに id / label を揃えた ROOM_LABEL_COUNT 件の配列（0-19 のみ） */
export function padRoomLabelSlots(rows) {
  const byOrder = new Map()
  for (const r of rows || []) {
    const o = Number(r?.sort_order)
    if (!isStandardRoomLabelSortOrder(o)) continue
    byOrder.set(o, {
      sort_order: o,
      id: r?.id ?? null,
      label: String(r?.label ?? ''),
    })
  }
  return Array.from({ length: ROOM_LABEL_COUNT }, (_, i) => ({
    sort_order: i,
    id: byOrder.get(i)?.id ?? null,
    label: byOrder.get(i)?.label ?? '',
  }))
}

/** PDF 固定文字 101-103 を3件に揃える */
export function padRoomLabelPdfFixedSlots(rows) {
  const byOrder = new Map()
  for (const r of rows || []) {
    const o = Number(r?.sort_order)
    if (!isRoomLabelFixedTextOrder(o)) continue
    byOrder.set(o, {
      sort_order: o,
      id: r?.id ?? null,
      label: String(r?.label ?? ''),
    })
  }
  return ROOM_LABEL_FIXED_TEXT_ORDERS.map((order) => ({
    sort_order: order,
    id: byOrder.get(order)?.id ?? null,
    label: byOrder.get(order)?.label ?? '',
  }))
}

/** PDF 固定文字 sort_order → fixed1/2/3 */
export function readPdfFixedTextsFromRoomLabels(rows) {
  const out = { fixed1: '', fixed2: '', fixed3: '' }
  for (let i = 0; i < ROOM_LABEL_FIXED_TEXT_ORDERS.length; i++) {
    const order = ROOM_LABEL_FIXED_TEXT_ORDERS[i]
    const key = ROOM_LABEL_FIXED_TEXT_KEYS[i]
    const hit = (rows || []).find((r) => Number(r?.sort_order) === order)
    out[key] = String(hit?.label ?? '')
  }
  return out
}

/** @deprecated readPdfFixedTextsFromRoomLabels の別名 */
export const readPdfFixedTextsFromRoomLabelTemplates = readPdfFixedTextsFromRoomLabels

export function emptyRoomLabelSlots() {
  return padRoomLabelSlots([])
}

export function emptyRoomLabelPdfFixedSlots() {
  return padRoomLabelPdfFixedSlots([])
}

/** 案件 room_labels が保存済みか（0-19 のいずれかに文字あり。101-103 は判定に含めない） */
export function roomLabelsLookUsable(arr) {
  return (
    Array.isArray(arr) &&
    arr.some((r) => {
      const o = Number(r?.sort_order)
      return isStandardRoomLabelSortOrder(o) && String(r?.label ?? '').trim().length > 0
    })
  )
}

/** 部屋タブ: ルームラベルが DB 保存済みかつ当該 sort_order の label が空 */
export function isRoomLabelSavedButBlank(roomOrder, labels, { persisted = false } = {}) {
  const ord = Number(roomOrder)
  if (!persisted || !Number.isFinite(ord) || !isPhotoTabRoomOrder(ord)) return false
  const hit = (labels || []).find((r) => Number(r?.sort_order) === ord)
  if (!hit) return false
  return !String(hit?.label ?? '').trim()
}
