/** 見積グリッド PDF: def1/def2 の最大行数（1枚目左右共通） */
import {
  formatSchedulePdfDisplayLabel,
  scheduleLabelTemplateById,
} from '../constants/workLargeSchedule.js'

export const ESTIMATE_PDF_DEF_MAX = 42

/** 後方互換デフォルト（master_pdf_applications_maps 未設定時） */
export const ESTIMATE_PDF_APPLICATIONS_CODES = ['2']

export const ESTIMATE_PDF_FIXED_KEYS = ['fixed1', 'fixed2', 'fixed3']

const DEF_KEY_RE = /^(def1|def2)-(\d+)$/
const SPECIAL_KEY_RE = /^special[1-5]\d+-\d+$/
const SPECIAL_HDR_RE = /^special[1-5]_hdr$/
const SCHEDULE_FIELD_RE = /^schedule-\d+_(label|symbol|start|end)$/
const WORK_LARGE_SCHEDULE_COUNT = 14

function formatSchedulePdfDate(isoDate) {
  const raw = String(isoDate ?? '').trim()
  if (!raw) return ''
  const m = raw.match(/^(\d{4})-(\d{2})-(\d{2})/)
  if (!m) return ''
  return `${m[2]}/${m[3]}`
}

/** mm/dd（NULL なら空文字） */
export function formatSchedulePdfStart(startOn) {
  return formatSchedulePdfDate(startOn)
}

/** ～mm/dd（終了日 NULL なら空文字）→ PDF 4.5段レイアウトでは mm/dd のみ（区切りは | リテラル） */
export function formatSchedulePdfEnd(endOn) {
  return formatSchedulePdfDate(endOn)
}

/** @deprecated 4分割レイアウトでは start/end を使用 */
export function formatSchedulePdfPeriod(startOn, endOn) {
  const start = formatSchedulePdfStart(startOn)
  const end = formatSchedulePdfDate(endOn)
  if (!start && !end) return ''
  if (start && end) return `${start}~${end}`
  if (start) return `${start}~`
  return `~${end}`
}

function resolveScheduleSymbol(statusId, statusById) {
  if (statusId == null || statusId === '') return ''
  const st = statusById.get(Number(statusId))
  return st?.symbol != null ? String(st.symbol) : ''
}

/** 状態1・状態2の symbol を半角スペースなしで結合 */
export function buildSchedulePdfSymbol(row, statusById) {
  if (!row) return ''
  const primary = resolveScheduleSymbol(row.schedule_status_id, statusById)
  const secondary = resolveScheduleSymbol(row.schedule_secondary_status_id, statusById)
  return `${primary}${secondary}`
}

/**
 * work_large_schedules 14行 → PDF payload（schedule-1_* … schedule-14_*）
 * @param {Array} scheduleRows sort_order 0-13
 * @param {Array} statusOptions master_work_schedule_statuses
 * @param {Array} [scheduleLabelTemplates] schedule_label_templates（PDF label 用 category 解決）
 */
export function buildSchedulePdfPayloadFields(
  scheduleRows,
  statusOptions,
  scheduleLabelTemplates = [],
) {
  const statusById = new Map(
    (statusOptions || []).map((st) => [Number(st.id), st])
  )
  const templateById = scheduleLabelTemplateById(scheduleLabelTemplates)
  const byOrder = new Map()
  for (const row of scheduleRows || []) {
    const order = Number(row?.sort_order)
    if (!Number.isFinite(order) || order < 0 || order > 13) continue
    byOrder.set(order, row)
  }

  const out = {}
  for (let order = 0; order < WORK_LARGE_SCHEDULE_COUNT; order++) {
    const itemNo = order + 1
    const row = byOrder.get(order)
    out[`schedule-${itemNo}_label`] = row
      ? formatSchedulePdfDisplayLabel(row, templateById)
      : ''
    out[`schedule-${itemNo}_symbol`] = buildSchedulePdfSymbol(row, statusById)
    out[`schedule-${itemNo}_start`] = row ? formatSchedulePdfStart(row.start_on) : ''
    out[`schedule-${itemNo}_end`] = row ? formatSchedulePdfEnd(row.end_on) : ''
  }
  return out
}

function parseDefKeyIndex(key, prefix) {
  const m = key.match(new RegExp(`^${prefix}-(\\d+)$`))
  return m ? parseInt(m[1], 10) : 0
}

/** def1-* / def2-* の最大連番 */
export function getDefGroupMaxIndex(payload, prefix) {
  let max = 0
  for (const key of Object.keys(payload || {})) {
    if (!key.startsWith(`${prefix}-`)) continue
    max = Math.max(max, parseDefKeyIndex(key, prefix))
  }
  return max
}

/** word_count 結合後ペイロードの溢れ情報 */
export function getEstimatePdfOverflowInfo(payload) {
  const def1Max = getDefGroupMaxIndex(payload, 'def1')
  const def2Max = getDefGroupMaxIndex(payload, 'def2')
  return {
    def1Max,
    def2Max,
    def1Overflow: def1Max > ESTIMATE_PDF_DEF_MAX,
    def2Overflow: def2Max > ESTIMATE_PDF_DEF_MAX,
    hasOverflow: def1Max > ESTIMATE_PDF_DEF_MAX || def2Max > ESTIMATE_PDF_DEF_MAX,
  }
}

export function buildEstimatePdfOverflowMessage(info) {
  const lines = []
  if (info.def1Overflow) {
    lines.push(`def1: ${info.def1Max} 行（最大 ${ESTIMATE_PDF_DEF_MAX}）`)
  }
  if (info.def2Overflow) {
    lines.push(`def2: ${info.def2Max} 行（最大 ${ESTIMATE_PDF_DEF_MAX}）`)
  }
  lines.push('')
  lines.push(`続行すると、def1/def2 それぞれ先頭 ${ESTIMATE_PDF_DEF_MAX} 行のみ PDF に出力されます。`)
  lines.push(`${ESTIMATE_PDF_DEF_MAX + 1}行目以降は出力されません。`)
  return lines.join('\n')
}

/** def1/def2 をそれぞれ独立に cap */
export function capEstimatePdfDefPayload(payload) {
  const capped = { ...payload }
  for (const prefix of ['def1', 'def2']) {
    for (const key of Object.keys(capped)) {
      if (!key.startsWith(`${prefix}-`)) continue
      const idx = parseDefKeyIndex(key, prefix)
      if (idx > ESTIMATE_PDF_DEF_MAX) {
        delete capped[key]
      }
    }
  }
  return capped
}

function flattenSlotToPageValues(slot, keyPrefix, out, { preserveLeadingSpace = false } = {}) {
  if (!slot || typeof slot !== 'object') return
  let display = String(slot.display ?? '')
  if (preserveLeadingSpace) {
    display = display.replace(/\s+$/u, '')
  } else {
    display = display.trim()
  }
  out[`${keyPrefix}_display`] = display
  if (slot.is_highlight) {
    out[`${keyPrefix}_is_highlight`] = 'true'
  }
  if (slot.is_contractor_label) {
    out[`${keyPrefix}_is_contractor_label`] = 'true'
  }
}

/** fixed1/2/3 をそのまま載せる。line 展開・上/下詰めは seed layout_config + Edge */
function applyFixedTextFieldsToPages(page0, page1, payload) {
  for (const key of ESTIMATE_PDF_FIXED_KEYS) {
    if (!(key in (payload || {}))) continue
    const text = String(payload[key] ?? '')
    page0[key] = text
    page1[key] = text
  }
}

export function convertEstimatePayloadToPdfValues(payload) {
  const page0 = { page: 0 }
  const page1 = { page: 1 }

  for (const [key, value] of Object.entries(payload || {})) {
    if (ESTIMATE_PDF_FIXED_KEYS.includes(key)) {
      continue
    }

    if (SCHEDULE_FIELD_RE.test(key)) {
      page0[key] = String(value ?? '').trim()
      continue
    }

    if (key === 'roomlabel') {
      const arr = Array.isArray(value) ? value : []
      for (let i = 0; i <= 9; i++) {
        page1[`roomlabel_${i}`] = String(arr[i] ?? '').trim()
      }
      continue
    }

    if (SPECIAL_HDR_RE.test(key)) {
      page1[key] = String(value ?? '').trim()
      continue
    }

    if (DEF_KEY_RE.test(key)) {
      flattenSlotToPageValues(value, key, page0, { preserveLeadingSpace: true })
      continue
    }

    if (SPECIAL_KEY_RE.test(key)) {
      flattenSlotToPageValues(value, key, page1)
    }
  }

  applyFixedTextFieldsToPages(page0, page1, payload)

  return [page0, page1]
}

/** master_pdf_applications_maps 行 → create_pdf_layout 用 applications_codes */
export function applicationsCodesFromPdfApplicationsMap(row) {
  const code = String(row?.applications_code ?? '').trim()
  return code ? [code] : ESTIMATE_PDF_APPLICATIONS_CODES
}

/**
 * master_pdf_applications_maps 行 → create_pdf_layout の page_count（page0 以外）。
 * content_page_count 未設定時は applications_code から後方互換。
 */
export function estimatePdfContentPageCount(row) {
  if (row == null) return 1
  const raw = row.content_page_count
  if (raw !== null && raw !== undefined && raw !== '') {
    const n = Number(raw)
    if (Number.isFinite(n) && n >= 0) return Math.floor(n)
  }
  const code = String(row.applications_code ?? '2').trim()
  if (code === '3') return 0
  return 1
}

export function buildEstimatePdfFileName(work) {
  const housing = work?.housing_details || {}
  const sanitize = (s) => String(s ?? '').trim().replace(/[\s\\/:*?"<>|]+/g, '')
  const name = sanitize(housing.name) || '無題'
  const building = sanitize(housing.building)
  const room = sanitize(work?.room)
  const d = new Date()
  const ymd =
    `${d.getFullYear()}` +
    `${String(d.getMonth() + 1).padStart(2, '0')}` +
    `${String(d.getDate()).padStart(2, '0')}`
  return `指示-${name}-${building}-${room}_${ymd}.pdf`
}

export const ESTIMATE_PDF_NAME_PREFIX = '指示-'

/** スロット/ホーム PDF 一覧から見積グリッド PDF（指示-）を除外 */
export function filterSlotPdfFiles(pdfFiles) {
  if (!Array.isArray(pdfFiles)) return []
  return pdfFiles.filter((f) => !f?.name?.startsWith(ESTIMATE_PDF_NAME_PREFIX))
}

/** work-pdf 一覧から見積グリッド PDF（指示- プレフィックス）の最新1件 */
export function pickLatestEstimateGridPdf(pdfFiles) {
  if (!Array.isArray(pdfFiles)) return null
  const matches = pdfFiles.filter((f) => f?.name?.startsWith(ESTIMATE_PDF_NAME_PREFIX))
  if (!matches.length) return null
  return matches.sort((a, b) => {
    const ta = a.created_at ? new Date(a.created_at).getTime() : 0
    const tb = b.created_at ? new Date(b.created_at).getTime() : 0
    return tb - ta
  })[0]
}
