<template>
  <div class="room-label-template-editor">
    <div class="editor-header">
      <div class="header-content">
        <button
          class="save-btn"
          @click="saveLabels"
          :disabled="saving || !isDirty"
        >
          {{ saving ? '保存中' : '保存' }}
        </button>
        <h3>見積用固定文字</h3>
      </div>
      <p class="editor-description">見積PDF固定文字・デフォルト部屋名・入力補助用ラベルを設定します</p>
      <span v-if="isDirty" class="dirty-indicator">※ 未保存の変更があります</span>
    </div>

    <div v-if="loading" class="loading-state">読み込み中</div>

    <div v-else class="labels-form">
      <h4 class="section-heading">PDF固定文字</h4>
      <div
        v-for="(order, index) in ROOM_LABEL_FIXED_TEXT_ORDERS"
        :key="`fixed-${order}`"
        class="label-row label-row--full"
      >
        <textarea
          v-model="fixedTexts[index]"
          @input="markDirty"
          class="label-textarea label-textarea--pdf-fixed"
          :placeholder="`固定文字 ${index + 1}`"
          rows="3"
        />
      </div>

      <div class="section-divider" role="separator"></div>
      <h4 class="section-heading">デフォルト部屋名</h4>

      <div
        v-for="index in defaultRoomOrders"
        :key="`room-${index}`"
        class="label-row"
      >
        <span class="label-number">{{ index }}.</span>
        <input
          type="text"
          v-model="labels[index]"
          @input="markDirty"
          class="label-input"
          :placeholder="`ラベル ${index}`"
        />
      </div>

      <div class="section-divider" role="separator"></div>
      <h4 class="section-heading">入力補助用</h4>

      <div
        v-for="index in assistRoomOrders"
        :key="`assist-${index}`"
        class="label-row"
      >
        <span class="label-number">{{ index }}.</span>
        <input
          type="text"
          v-model="labels[index]"
          @input="markDirty"
          class="label-input label-input--extended"
          :placeholder="`ラベル ${index}`"
        />
      </div>
    </div>
  </div>
</template>

<script setup>
import { computed, ref, onMounted } from 'vue'
import { supabaseService } from '../services/supabase'
import { indexedDBService } from '../utils/indexedDB'
import {
  ROOM_LABEL_COUNT,
  ROOM_LABEL_FIXED_TEXT_ORDERS,
  ROOM_LABEL_INSERT_MENU_ORDER_MIN,
  padRoomLabelSlots,
  PHOTO_TAB_ROOM_ORDER_MAX,
} from '../constants/roomLabelSlots.js'
import { useDialog } from '../composables/useDialog'

const loading = ref(false)
const saving = ref(false)
const isDirty = ref(false)
const labels = ref(Array(ROOM_LABEL_COUNT).fill(''))
const fixedTexts = ref(ROOM_LABEL_FIXED_TEXT_ORDERS.map(() => ''))
const dialog = useDialog()

const defaultRoomOrders = computed(() =>
  Array.from({ length: PHOTO_TAB_ROOM_ORDER_MAX + 1 }, (_, i) => i)
)

const assistRoomOrders = computed(() =>
  Array.from(
    { length: ROOM_LABEL_COUNT - ROOM_LABEL_INSERT_MENU_ORDER_MIN },
    (_, i) => i + ROOM_LABEL_INSERT_MENU_ORDER_MIN
  )
)

function applyTemplatesFromRows(rows) {
  labels.value = padRoomLabelSlots(rows).map((t) => t.label || '')
  fixedTexts.value = ROOM_LABEL_FIXED_TEXT_ORDERS.map((order) => {
    const hit = (rows || []).find((t) => Number(t.sort_order) === order)
    return hit?.label || ''
  })
}

async function loadLabels() {
  loading.value = true
  try {
    const result = await supabaseService.getRoomLabelTemplates()
    if (result.room_label_templates) {
      const sorted = result.room_label_templates.sort((a, b) => a.sort_order - b.sort_order)
      applyTemplatesFromRows(sorted)
    } else {
      labels.value = Array(ROOM_LABEL_COUNT).fill('')
      fixedTexts.value = ROOM_LABEL_FIXED_TEXT_ORDERS.map(() => '')
    }
    isDirty.value = false
  } catch (err) {
    console.error('Failed to load room label templates:', err)
    await dialog.alert('部屋名テンプレートの読み込みに失敗しました: ' + err.message, { title: 'エラー' })
  } finally {
    loading.value = false
  }
}

function markDirty() {
  isDirty.value = true
}

async function saveLabels() {
  saving.value = true
  try {
    const labelsToSave = labels.value.map((label, index) => ({
      sort_order: index,
      label: label || '',
    }))
    for (let i = 0; i < ROOM_LABEL_FIXED_TEXT_ORDERS.length; i++) {
      labelsToSave.push({
        sort_order: ROOM_LABEL_FIXED_TEXT_ORDERS[i],
        label: fixedTexts.value[i] || '',
      })
    }

    await supabaseService.saveRoomLabelTemplates(labelsToSave)

    const result = await supabaseService.getRoomLabelTemplates()
    if (result.room_label_templates) {
      await indexedDBService.saveTemplate('room_label_templates', result.room_label_templates)
    }

    isDirty.value = false
    await dialog.alert('保存しました', { title: '成功' })
  } catch (err) {
    console.error('Failed to save room label templates:', err)
    await dialog.alert('保存に失敗しました: ' + err.message, { title: 'エラー' })
  } finally {
    saving.value = false
  }
}

function reload() {
  loadLabels()
}

onMounted(() => {
  loadLabels()
})

defineExpose({
  loading,
  reload,
})
</script>

