import { scheduleColumnHeadersFromTemplates } from '../constants/workLargeSchedule.js'
import { SCHEDULE_GRID_SORT_KEYS } from './scheduleGridFilters.js'

function compareNullableDate(a, b, ascending) {
  const ta = a ? new Date(a).getTime() : NaN
  const tb = b ? new Date(b).getTime() : NaN
  const aValid = Number.isFinite(ta)
  const bValid = Number.isFinite(tb)
  if (!aValid && !bValid) return 0
  if (!aValid) return 1
  if (!bValid) return -1
  const cmp = ta - tb
  return ascending ? cmp : -cmp
}

function compareWorkCode(a, b, ascending) {
  const na = Number(a)
  const nb = Number(b)
  const aValid = Number.isFinite(na)
  const bValid = Number.isFinite(nb)
  if (!aValid && !bValid) return 0
  if (!aValid) return 1
  if (!bValid) return -1
  const cmp = na - nb
  return ascending ? cmp : -cmp
}

function compareScheduleGridItems(a, b, sortKey, ascending) {
  switch (sortKey) {
    case SCHEDULE_GRID_SORT_KEYS.ORDERED_ON:
      return compareNullableDate(a.ordered_on, b.ordered_on, ascending)
    case SCHEDULE_GRID_SORT_KEYS.WORK_CODE:
      return compareWorkCode(a.work_code, b.work_code, ascending)
    case SCHEDULE_GRID_SORT_KEYS.CREATED_AT:
    default:
      return compareNullableDate(a.schedule_created_at, b.schedule_created_at, ascending)
  }
}

/** MC マスタ順でグループ化し、MC 内で指定キー順に work 行をソート */
export function sortScheduleGridWorkItemsByMc(workItems, mcs = [], sortOptions = {}) {
  const sortKey = sortOptions.sortKey ?? SCHEDULE_GRID_SORT_KEYS.CREATED_AT
  const ascending = sortOptions.sortAscending !== false
  const mcOrder = new Map((mcs || []).map((mc, index) => [Number(mc.id), index]))

  return [...(workItems || [])].sort((a, b) => {
    const mcA =
      a.mc_id != null && a.mc_id !== '' ? Number(a.mc_id) : null
    const mcB =
      b.mc_id != null && b.mc_id !== '' ? Number(b.mc_id) : null
    const orderA = mcA != null ? (mcOrder.get(mcA) ?? 9999) : 10000
    const orderB = mcB != null ? (mcOrder.get(mcB) ?? 9999) : 10000
    if (orderA !== orderB) return orderA - orderB
    if (mcA !== mcB) return (mcA ?? 0) - (mcB ?? 0)

    const inner = compareScheduleGridItems(a, b, sortKey, ascending)
    if (inner !== 0) return inner
    return String(a.work_id).localeCompare(String(b.work_id))
  })
}

export function resolveScheduleGridMcLabel(mcId, mcs = []) {
  if (mcId == null || mcId === '') return 'MC未設定'
  const mc = (mcs || []).find((row) => Number(row.id) === Number(mcId))
  const label = String(mc?.label ?? '').trim()
  return label || `MC ${mcId}`
}

/** company+mc テンプレ: 対象 work の mc_id と一致するもののみ */
export function scheduleLabelTemplatesForMc(templates, mcId) {
  const list = templates || []
  if (mcId == null || mcId === '') return []
  return list.filter((tpl) => Number(tpl.mc_id) === Number(mcId))
}

export function scheduleColumnHeadersForMc(templates, mcId) {
  return scheduleColumnHeadersFromTemplates(scheduleLabelTemplatesForMc(templates, mcId))
}

/**
 * MC 見出し行 + work 行の平坦リスト
 * @returns {Array<{ type: 'mc-header', key: string, mcId: number|null, mcLabel: string, columnHeaders: string[] } | { type: 'work', key: string, item: object }>}
 */
export function buildScheduleGridDisplayRows(workItems, { mcs = [], templates = [] } = {}) {
  const displayRows = []
  let lastMcKey = null

  for (const item of workItems || []) {
    const mcKey =
      item.mc_id != null && item.mc_id !== '' ? String(item.mc_id) : 'unknown'
    if (mcKey !== lastMcKey) {
      const mcId = mcKey === 'unknown' ? null : Number(item.mc_id)
      displayRows.push({
        type: 'mc-header',
        key: `mc-${mcKey}`,
        mcId,
        mcLabel: resolveScheduleGridMcLabel(mcId, mcs),
        columnHeaders: scheduleColumnHeadersForMc(templates, mcId),
      })
      lastMcKey = mcKey
    }
    displayRows.push({
      type: 'work',
      key: `work-${item.work_id}`,
      item,
    })
  }

  return displayRows
}
